import stylesText from './activity-edit.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';

const styles = cssStyleSheet(stylesText);
import { ACTIVITY_TYPES, activityStartLocalDate } from '@motivation/shared';
import { activityStartLocalTime, withActivityStart } from '../health-utils.js';
import { getAppTimeZone } from '../../../services/app-timezone.service.js';
import type { Activity } from '@motivation/shared';

/** `synced` covers every read-only imported source: old Strava-API rows and Health Connect rows (story 250). */
/**
 * `'manual'` covers every row the owner owns — hand-logged entries and adopted calendar classes
 * alike (story 323); both are fully editable and neither is written back anywhere.
 * `'calendar-unadopted'` is a class that is still only a live projection of the Google Calendar
 * event, with no row to save to. `'synced'` is an ingested mirror, read-only but for its title.
 */
export type ActivitySourceMode = 'manual' | 'synced' | 'calendar-unadopted';

const template = document.createElement('template');
template.innerHTML = `
    <div class="edit-container">
        <p class="source-note" id="source-note" hidden></p>

        <div class="form-group">
            <label for="title">Title</label>
            <input type="text" id="title" class="form-input" placeholder="e.g. Morning run">
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="type">Type</label>
                <select id="type" class="form-select">
                    ${ACTIVITY_TYPES.map(t => `<option value="${t}">${t.charAt(0).toUpperCase() + t.slice(1).replace(/_/g, ' ')}</option>`).join('')}
                </select>
            </div>
            <div class="form-group">
                <label for="date">Date</label>
                <input type="date" id="date" class="form-input">
            </div>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="duration">Duration (min)</label>
                <input type="number" id="duration" class="form-input" min="0" placeholder="optional">
            </div>
            <div class="form-group">
                <label for="calories">Calories burned</label>
                <input type="number" id="calories" class="form-input" min="0" placeholder="optional">
            </div>
        </div>

        <div class="form-group">
            <!-- Story 299: the time of day the session began. Optional, and only meaningful on a
                 manual row — a synced row's start comes from the app that recorded it. -->
            <label for="start-time">Start time</label>
            <input type="time" id="start-time" class="form-input">
        </div>

        <div class="form-group">
            <label for="description">Notes</label>
            <input type="text" id="description" class="form-input" placeholder="optional">
        </div>

        <div class="action-buttons">
            <button class="btn-delete" id="btn-delete">Delete</button>
            <button class="btn-save" id="btn-save">Save</button>
        </div>
    </div>
`;

export class ActivityEdit extends HTMLElement {
    private _activity: Activity | null = null;
    private _sourceMode: ActivitySourceMode = 'manual';
    private _onSave: ((id: string, updates: Partial<Activity>) => void) | null = null;
    private _onDelete: ((id: string) => void) | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
    }

    connectedCallback() {
        const shadow = this.shadowRoot!;
        shadow.getElementById('btn-save')!.addEventListener('click', () => this.handleSave());
        shadow.getElementById('btn-delete')!.addEventListener('click', () => this.handleDelete());
    }

    set onSave(handler: (id: string, updates: Partial<Activity>) => void) {
        this._onSave = handler;
    }

    set onDelete(handler: (id: string) => void) {
        this._onDelete = handler;
    }

    set sourceMode(mode: ActivitySourceMode) {
        this._sourceMode = mode;
        this.applySourceMode();
    }

    private applySourceMode(): void {
        const shadow = this.shadowRoot!;
        const save = shadow.getElementById('btn-save') as HTMLButtonElement;
        const del = shadow.getElementById('btn-delete') as HTMLButtonElement;
        const note = shadow.getElementById('source-note') as HTMLElement;

        // Everything except the title is server-owned on synced rows (story 253).
        const lockNonTitleFields = this._sourceMode === 'synced';
        for (const id of ['type', 'date', 'duration', 'calories', 'description', 'start-time']) {
            (shadow.getElementById(id) as HTMLInputElement | HTMLSelectElement).disabled = lockNonTitleFields;
        }

        switch (this._sourceMode) {
            case 'manual':
                save.hidden = false;
                del.hidden = false;
                note.hidden = true;
                note.textContent = '';
                break;
            case 'synced':
                // Synced rows accept a title-only PATCH (story 253) — HC sessions
                // arrive nameless and HC cannot receive a title back (records
                // belong to their writer). Delete stays available — the activity
                // will however come back on the next sync unless it is also gone
                // from the source.
                save.hidden = false;
                del.hidden = false;
                note.hidden = false;
                note.textContent = 'Synced activity. Only the title can be edited; deleting here only hides it until the next sync.';
                break;
            case 'calendar-unadopted':
                // Still just a projection: synthesized from Google Calendar on every load, with no
                // DB row, so neither save nor delete can do anything durable. The way in is the
                // day's "I was there" button, which creates the row (story 323).
                save.hidden = true;
                del.hidden = true;
                note.hidden = false;
                note.textContent = 'From Google Calendar. Tap “I was there” on the day to log it — then the time, duration, distance and exercises are yours to edit.';
                break;
        }
    }

    set activity(val: Activity) {
        this._activity = val;
        this.populateForm();
    }

    get activity(): Activity | null {
        return this._activity;
    }

    private populateForm(): void {
        const a = this._activity;
        if (!a) return;
        const shadow = this.shadowRoot!;

        (shadow.getElementById('title') as HTMLInputElement).value = a.title;
        (shadow.getElementById('type') as HTMLSelectElement).value = a.type;
        (shadow.getElementById('date') as HTMLInputElement).value = a.date;
        (shadow.getElementById('duration') as HTMLInputElement).value = a.duration_minutes ? String(a.duration_minutes) : '';
        (shadow.getElementById('calories') as HTMLInputElement).value = a.calories_burned ? String(a.calories_burned) : '';
        (shadow.getElementById('description') as HTMLInputElement).value = a.description ?? '';
        (shadow.getElementById('start-time') as HTMLInputElement).value = activityStartLocalTime(a.metadata);
    }

    /**
     * Story 374 (pwa-activity-03): the start is rebuilt only when the date or the time was changed.
     * The form shows the start in the current zone, where its local day can differ from
     * `activity.date` — a 23:30 Amsterdam run is 06:30 the next morning in Tokyo — so rebuilding
     * it from `activity.date` on every save moved it a whole day. A new time keeps the start's own
     * local day; a new date takes the form's.
     */
    private metadataWithStart(date: string, startTime: string): string | null {
        const a = this._activity!;
        const timeZone = getAppTimeZone();
        const shownTime = activityStartLocalTime(a.metadata, timeZone);
        if (date === a.date && startTime === shownTime) return a.metadata;
        const day = date === a.date ? (activityStartLocalDate(a.metadata, timeZone) ?? date) : date;
        return withActivityStart(a.metadata, day, startTime, timeZone);
    }

    private handleSave(): void {
        if (!this._activity || !this._onSave) return;
        const shadow = this.shadowRoot!;

        const title = (shadow.getElementById('title') as HTMLInputElement).value.trim();
        if (!title) return;

        // Synced rows: the server accepts a title-only PATCH and rejects
        // anything else (story 253).
        if (this._sourceMode === 'synced') {
            this._onSave(this._activity.id, { title });
            return;
        }

        const duration = parseInt((shadow.getElementById('duration') as HTMLInputElement).value, 10);
        const calories = parseInt((shadow.getElementById('calories') as HTMLInputElement).value, 10);
        const date = (shadow.getElementById('date') as HTMLInputElement).value;
        const startTime = (shadow.getElementById('start-time') as HTMLInputElement).value;

        const updates: Partial<Activity> = {
            title,
            type: (shadow.getElementById('type') as HTMLSelectElement).value,
            date,
            // Story 371 (pwa-activity-09): a cleared field is `null`, which clears it —
            // `undefined` is dropped by JSON, so a mistyped 6000 kcal stuck for good.
            description: (shadow.getElementById('description') as HTMLInputElement).value.trim() || null,
            duration_minutes: isNaN(duration) ? null : duration,
            calories_burned: isNaN(calories) ? null : calories,
            // Story 299: editing the date moves the instant with it, and clearing the time clears it.
            metadata: this.metadataWithStart(date, startTime),
        };

        this._onSave(this._activity.id, updates);
    }

    private handleDelete(): void {
        if (!this._activity || !this._onDelete) return;
        const title = this._activity.title;
        // Story 354: an adopted class is the only `calendar` row that reaches here (an unadopted
        // one hides Delete), and deleting it is the "I didn't go" path story 323 chose.
        const message = this._sourceMode === 'synced'
            ? `Delete "${title}"?\n\nThis activity is synced and will reappear on the next sync unless it is also removed at the source.`
            : this._activity.source === 'calendar'
                ? `Delete "${title}"?\n\nThis undoes "I was there": the class goes back to an unlogged Google Calendar entry `
                    + 'you can log again, as long as it is still in your calendar. Distance and exercises added to it are deleted.'
                : `Delete "${title}"?`;
        if (confirm(message)) {
            this._onDelete(this._activity.id);
        }
    }
}

if (!customElements.get('activity-edit')) {
    customElements.define('activity-edit', ActivityEdit);
}
